import json
from collections import Counter

with open("дані/користувачі.json", encoding="utf-8") as f:
    users = json.load(f)

counts = Counter()
for u in users:
    email = u.get("email")
    if isinstance(email, str):
        e = email.strip().lower()
        if e:
            counts[e] += 1

for email in sorted(counts):
    if counts[email] > 1:
        print(email, counts[email])
